local bxor=bit32 and bit32.bxor or bit and bit.bxor or(function(a,b)local r=0 for i=0,7 do local ba=a%2 local bb=b%2 if ba~=bb then r=r+2^i end a=(a-ba)/2 b=(b-bb)/2 end return r end)
local k={0xE7,0xA3,0x5B,0x9C,0xD1,0x4F,0x62,0x08}
local bb="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function bd(s)
 local r,t={},{}
 for i=1,#s do
  local c=bb:find(s:sub(i,i),1,true)-1
  if c>=0 then t[#t+1]=c end
  if #t==4 then
   r[#r+1]=string.char(t[1]*4+math.floor(t[2]/16))
   r[#r+1]=string.char(t[2]%16*16+math.floor(t[3]/4))
   r[#r+1]=string.char(t[3]%4*64+t[4])
   t={}
  end
 end
 return table.concat(r)
end
local function xd(s)
 local r={}
 for i=1,#s do r[i]=string.char(bxor(string.byte(s,i),k[(i-1)%#k+1])) end
 return table.concat(r)
end
